int max_len(int N,int *A){
    int best=0;
    int total=1<<N;
    for(int mask=0; mask<total; mask++){
        int len=0;
        for(int i=0;i<N;i++) if(mask>>i & 1) len++;
        if(len<=best || len%2) continue;
        if(is_1122_subseq(A,N,mask)) best=len;
    }
    return best;
}

